function identityKey(user=data?.user){return (user?.schoolId||localStorage.getItem('cfc-school')||'local')+':'+(user?.id||'');}
let dbPromise;
function db(){return dbPromise??=new Promise((resolve,reject)=>{const req=indexedDB.open('cfc-pilot',1);req.onupgradeneeded=()=>req.result.createObjectStore('kv');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function storage(key,value){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('kv',value===undefined?'readonly':'readwrite');const req=value===undefined?tx.objectStore('kv').get(key):tx.objectStore('kv').put(value,key);let result;req.onsuccess=()=>result=req.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);});}
