async function api(path,body,operation){let response;try{response=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:{...((data?.user?.schoolId||localStorage.getItem('cfc-school'))&&!path.startsWith('auth/login')?{'X-CFC-School':data?.user?.schoolId||localStorage.getItem('cfc-school')} :{}),...(body===undefined?{}:{'Content-Type':'application/json','X-CFC-Client':'pilot',...(operation?{'X-Operation-Id':operation}:{})})},body:body===undefined?undefined:JSON.stringify(body)});}catch(error){error.network=true;throw error;}const json=await response.json().catch(()=>({}));if(!response.ok){const e=new Error(json.error||`Operação não concluída (${response.status}).`);e.status=response.status;throw e;}return json;}
async function refresh(){if(localStorage.getItem('cfc-loggedout')){showLogin();return;}try{const me=await api("auth/me");if(me.mustChangePassword){location.href="/account/";return;}if(["Aluno","Instrutor"].includes(me.role)){location.href="/portal/";return;}data=await api(snapshotPath());data.user.schoolId=me.schoolId||'';data.user.schoolName=me.schoolName||'';localStorage.setItem('cfc-school',me.schoolId||'');if(['Aluno','Instrutor'].includes(data.user.role)){location.href='/portal/';return;}offline=false;await loadRealExtras();localStorage.setItem('cfc-user',identityKey());await storage('snapshot:'+identityKey(),data);queue=await storage(queueKey())||[];showShell();render();await flush();}catch(e){if(e.status===428){location.href="/account/";return;}if(e.status===401||e.status===403&&e.message.includes('outra autoescola')){data=null;showLogin();return;}const user=data?.user?identityKey():localStorage.getItem('cfc-user');const cached=user?await storage('snapshot:'+user):null;if(!e.network||!cached){toast(e.message||'Não foi possível carregar o aplicativo.');return;}data=cached;offline=true;queue=await storage(queueKey())||[];showShell();render();}}
function updateConnection(){$('#connection').textContent=offline?'Servidor indisponível · modo offline':'● Online';$('#sync-state').innerHTML=queue.length?`<button class="small ghost" data-action="queue">${queue.length} operação(ões) aguardando sincronização</button>`:(offline?'Dados locais · tentando reconectar ao servidor':'Dados sincronizados · '+new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}));}
async function command(action,body){const operation=id();if(body.id&&['student','instructor','vehicle','lead','task','template','package','unit','user'].includes(action))body.expectedRevision=data.revision;try{const result=await api('commands/'+action,body,operation);if(result.studentId)currentStudent=result.studentId;await refresh();return result;}catch(e){if(!e.network)throw e;const permitted=['matriculate','student','enroll','lesson','receive','entry','lead','task','message-draft'];if(!permitted.includes(action))throw new Error('Esta operação precisa de conexão com o servidor.');queue.push({schoolId:data.user.schoolId||'',owner:data.user.id,id:operation,action,body,created:new Date().toISOString(),error:''});await storage(queueKey(),queue);offline=true;updateConnection();toast('Operação guardada neste dispositivo. A confirmação ocorrerá após sincronização.');return {queued:true};}}
async function flush(){if(flushing||offline||!queue.length)return;flushing=true;try{while(queue.length){const op=queue[0];if(op.schoolId&&op.schoolId!==data.user.schoolId||op.owner&&op.owner!==data.user.id){op.error='Operação vinculada a outro acesso. Entre com a escola e usuário de origem.';}if(op.error)break;try{await api('commands/'+op.action,op.body,op.id);queue.shift();await storage(queueKey(),queue);}catch(e){if(e.network){offline=true;break;}op.error=e.message;await storage(queueKey(),queue);toast('Uma operação offline precisa de revisão: '+e.message);break;}}const schoolId=data.user.schoolId,schoolName=data.user.schoolName;data=await api(snapshotPath());data.user.schoolId=schoolId;data.user.schoolName=schoolName;await storage('snapshot:'+identityKey(),data);render();}catch(e){if(e.network)offline=true;}finally{flushing=false;updateConnection();}}
