function options(items,value){return items.map(x=>{const val=Array.isArray(x)?x[0]:x,label=Array.isArray(x)?x[1]:x;return `<option value="${esc(val)}" ${String(value)===String(val)?'selected':''}>${esc(label)}</option>`;}).join('');}
function field(f,value){const [key,label,type='text',opts=null,required=false]=f;const full=type==='textarea'||key==='notes'||key==='address';if(type==='checkbox')return `<label class="check-label ${full?'full':''}"><input type="checkbox" name="${key}" ${value?'checked':''}>${esc(label)}</label>`;let input;if(type==='select')input=`<select id="field-${key}" name="${key}" ${required?'required':''}>${options(opts,value)}</select>`;else if(type==='textarea')input=`<textarea id="field-${key}" name="${key}" rows="4" maxlength="30000" ${required?'required':''}>${esc(value||'')}</textarea>`;else input=`<input id="field-${key}" name="${key}" type="${type}" value="${esc(value??'')}" ${type==='number'?'step="0.01" min="0"':''} ${required?'required':''} ${type==='password'?'autocomplete="new-password"':''}>`;return `<div class="form-field ${full?'full':''}"><label for="field-${key}">${esc(label)}</label>${input}</div>`;}
