function receipt(x){modal('Recibo de pagamento',`<div class="eyebrow">${esc(x.receipt)}</div><h3>${esc(name('students',x.studentId))}</h3><div class="receipt-total">${money(x.amount)}</div><dl class="detail-grid"><div><dt>Forma</dt><dd>${esc(x.method)}</dd></div><div><dt>Data</dt><dd>${date(x.date)}</dd></div><div><dt>Unidade</dt><dd>${esc(name('units',x.unitId))}</dd></div></dl><p style="margin-top:20px">${esc(x.description)}</p>${x.voided?'<div class="notice">Este recibo foi estornado.</div>':''}<p class="hint">Recibo interno. Este documento não é uma nota fiscal.</p><div class="form-actions">${button('Imprimir / PDF','print')}${button('Fechar','close-modal','',true)}</div>`,'FINANCEIRO');}
function lessonDetail(lessonId){const x=find('lessons',lessonId);const can=isTeam()||data.user.role==='Instrutor';modal('Detalhes da aula',`<h3>${esc(name('students',x.studentId))}</h3><p class="muted" style="margin:10px 0 20px">${date(x.start)} · ${time(x.start)} · ${x.minutes} minutos</p><dl class="detail-grid"><div><dt>Instrutor</dt><dd>${esc(name('instructors',x.instructorId))}</dd></div><div><dt>Veículo</dt><dd>${esc(name('vehicles',x.vehicleId))}</dd></div><div><dt>Situação</dt><dd>${pill(x.status)}</dd></div><div><dt>Validação externa</dt><dd>${x.validated?'Confirmada':'Não confirmada'}</dd></div></dl><p style="margin-top:20px">${esc(x.notes)}</p><div class="form-actions">${can&&(x.status==='Agendada'||data.user.role==='Administrador'&&data.policy.allowHistoricalStatusEdits)?button('Registrar realização / falta','lesson-status',x.id)+button('Cancelar','lesson-cancel',x.id):''}${isTeam()&&x.status==='Agendada'?button('Remarcar','lesson-reschedule',x.id):''}</div>`,'AGENDA');}
function examForm(){if(isTeam()&&!currentStudent){modal('Escolha o aluno',picker('exam-picker','exam-select'),'AGENDAMENTO DE EXAME');return;}form('Registrar agendamento de exame',[['enrollmentId','Matrícula','select',enrollmentOptions(),true],['type','Tipo','select',['Médico','Psicológico','Teórico','Prático']],['start','Data e hora','datetime-local',null,true],['location','Local / banca','text',null,true],['protocol','Protocolo externo (se já obtido)'],['instructorId','Instrutor para prática','select',[['','Selecione'],...data.instructors.map(x=>[x.id,x.name])]],['vehicleId','Veículo para prática','select',[['','Selecione'],...data.vehicles.map(x=>[x.id,x.name])]],['reason','Justificativa de liberação financeira','textarea']],{enrollmentId:data.enrollments.find(x=>x.studentId===currentStudent&&x.status==='Ativa')?.id||'',type:'Teórico',start:localDate(new Date(Date.now()+86400000))+'T09:00'},async values=>command('exam',values),'Gravação interna. Este formulário não agenda no DETRAN. Os pré-requisitos registrados serão conferidos.');}
async function handle(action,arg=''){
 if(await handleFinance(action,arg))return;if(await handleCommercial(action,arg))return;if(await handleCommunity(action,arg))return;if(await handleStudentResources(action,arg))return;if(await handleRealData(action,arg))return;if(await handleWorkspace(action,arg))return;
 switch(action){
 case 'navigate':page=arg;location.hash=arg;if(data.realData)await refresh();else render();break;
 case 'refresh':await refresh();toast(offline?'Dados locais carregados.':'Dados atualizados.');break;
 case 'logout':try{await api('auth/logout',{});}catch(e){if(!e.network)throw e;}localStorage.removeItem('cfc-user');localStorage.setItem('cfc-loggedout','1');data=null;chats=[];chatJid='';chatMessages=[];currentStudent='';chatComposeDrafts.clear();showLogin();break;
 case 'student':selectStudent(arg);studentTab='overview';page='student';location.hash='student';await refresh();break;
 case 'student-tab':studentTab=arg;if(data.realData&&arg==='journey')await refresh();else{if(['documents','overview'].includes(arg))await loadStudentResources();render();}break;
 case 'student-new':resourceForm('student');break;
 case 'student-edit':resourceForm('student',arg);break;
 case 'enroll':enrollForm(arg);break;
 case 'receive':receiveForm(arg);break;
 case 'lesson-new':lessonForm(arg);break;
 case 'lesson-detail':lessonDetail(arg);break;
 case 'lesson-reschedule':lessonForm(find('lessons',arg).studentId,find('lessons',arg));break;
 case 'lesson-status':form('Registrar aula',[['status','Situação','select',['Realizada','Falta']],['notes','Evolução, habilidades e dificuldades','textarea'],['reason','Justificativa da correção histórica','textarea']],{},async values=>command('lesson-status',{...values,id:arg}),'A realização interna não confirma a biometria no DETRAN.');break;
 case 'lesson-cancel':form('Cancelar aula',[['reason','Motivo','textarea',null,true]],{},async values=>command('lesson-status',{...values,id:arg,status:'Cancelada'}),'Cancelamentos fora do prazo exigem gerente ou administrador e justificativa.');break;
 case 'agenda-mode':agendaMode=arg;render();break;
 case 'agenda-today':agendaDate=today();if(data.realData)await refresh();else render();break;
 case 'agenda-prev':case 'agenda-next':{const d=new Date(agendaDate+'T12:00:00');d.setDate(d.getDate()+(action==='agenda-prev'?-1:1)*(agendaMode==='day'?1:7));agendaDate=localDate(d);if(data.realData)await refresh();else render();break;}
 case 'exam-new':examForm();break;
 case 'exam-result':form('Resultado do exame',[['status','Resultado','select',['Aprovado','Reprovado','Falta','Cancelado']]],{},async values=>command('exam-result',{...values,id:arg}),'Resultado informado manualmente. A consulta automática ainda depende da integração.');break;
 case 'entry-new':form('Lançamento financeiro',[['kind','Tipo','select',['Despesa','Receita','Débito','Crédito']],['enrollmentId','Matrícula (para débito/crédito)','select',enrollmentOptions()],['unitId','Unidade','select',unitOptions(),true],['amount','Valor (R$)','number',null,true],['method','Forma','select',['PIX','Dinheiro','Cartão','Boleto','Transferência','Ajuste']],['description','Descrição','text',null,true],['date','Data do lançamento / recibo','date',null,true],['reason','Justificativa de data ou exceção','textarea'],['due','Vencimento para débito extra','date']],{enrollmentId:data.enrollments.find(x=>x.studentId===currentStudent&&x.status==='Ativa')?.id||'',unitId:unit||find('students',currentStudent)?.unitId||data.units[0].id,kind:currentStudent?'Débito':'Despesa',method:'PIX',date:today(),due:today()},async values=>command('entry',values));break;
 case 'void':form('Estornar recebimento / crédito',[['reason','Justificativa','textarea',null,true]],{},async values=>command('void',{...values,id:arg}),'O estorno cria um lançamento de reversão e reabre os valores das parcelas. O registro original é preservado.');break;
 case 'closecash':form('Fechar caixa',[['unitId','Unidade','select',unitOptions(),true]],{unitId:unit||data.units[0].id},async values=>command('closecash',values),data.realData?'Serão incluídos os movimentos abertos de hoje da unidade. O histórico importado deve ser conferido no extrato.':'Todos os movimentos ainda abertos da unidade serão incluídos no fechamento.');break;
 case 'receipt':receipt(find('entries',arg));break;
 case 'lead-enroll':{const lead=find('leads',arg);const st=data.students.find(s=>s.name===lead.name||(lead.phone&&s.phone===lead.phone));newEnrollmentForm(st?.id||'',lead.id);break;}
 case 'wait-new':resourceForm('waitlist');break;
 case 'wait-remove':await command('wait-remove',{id:arg});render();toast('Aluno removido da fila.');break;
 case 'unit-view':unit=arg;page='dashboard';if(data.realData)await refresh();else render();break;
 case 'document-new':form('Gerar documento',[['enrollmentId','Matrícula','select',enrollmentOptions(),true],['templateId','Modelo','select',data.templates.map(t=>[t.id,t.name]),true]],{},async values=>{const result=await command('document',values);documentOpen(result);return 'keep';});break;
 case 'document-open':documentOpen(find('documents',arg));break;
 case 'request-new':form('Solicitar atendimento',[['title','Sua solicitação','textarea',null,true]],{},async values=>command('task',values));break;
 case 'policy':configurablePolicyForm();break;
 case 'message-new':form('Preparar mensagem',[['studentId','Aluno (opcional)','select',studentOptions()],['phone','Telefone com país e DDD'],['text','Mensagem','textarea',null,true]],{},async values=>command('message-draft',values),'Salvar prepara um rascunho. O envio real é uma ação separada.');break;
 case 'message-open':{const x=find('messages',arg);modal('Mensagem preparada',`<p>${esc(name('students',x.studentId))} · ${esc(x.phone)}</p><pre class="document-text" style="margin:20px 0">${esc(x.text)}</pre><div class="form-actions">${button('Enviar pela Evolution','message-send',x.id,true)}</div>`,'WHATSAPP');break;}
 case 'message-send':{const x=find('messages',arg);try{await api('integrations/evolution/send',{messageId:x.id,phone:x.phone,text:x.text},id());}finally{await refresh();}toast('Evolution aceitou o envio. A confirmação de entrega depende do provedor.');$('#modal').close();break;}
 case 'evolution-status':try{const result=await api('integrations/evolution');const state=result.status?.instance?.state;const text=!result.configured?'Evolution ainda não configurada no servidor.':state==='open'?'WhatsApp conectado.':state==='connecting'?'Conectando WhatsApp.':'Evolution disponível. Conecte o WhatsApp pelo QR Code.';if($('#evolution-status'))$('#evolution-status').textContent=text;toast(text);}catch(e){if($('#evolution-status'))$('#evolution-status').textContent=e.message;throw e;}break;
 case 'evolution-chats':{const result=await api('integrations/evolution/chats');chats=Array.isArray(result)?result:result.records||result.chats||[];render();toast(chats.length+' conversas carregadas.');break;}
 case 'chat-open':{const result=await api('integrations/evolution/messages',{jid:arg});chatJid=arg;chatMessages=(Array.isArray(result)?result:result.messages?.records||result.records||[]).slice().sort((a,b)=>Number(a.messageTimestamp)-Number(b.messageTimestamp));render();break;}
 case 'chat-send':{const targetJid=chatJid,text=$('#chat-compose').value.trim(),phone=targetJid.split('@')[0];if(!text)throw new Error('Escreva a mensagem.');const student=data.students.find(s=>s.phone.replace(/\D/g,'')===phone);const draft=await command('message-draft',{phone,text,studentId:student?.id||''});if(draft.queued)throw new Error('Rascunho guardado. O envio precisa de conexão.');try{await api('integrations/evolution/send',{messageId:draft.id,phone,text},id());chatComposeDrafts.delete(targetJid);}finally{await refresh();}await loadChat(targetJid);toast('Mensagem aceita pela Evolution.');break;}
 case 'evolution-connect':{const result=await api('integrations/evolution/connect',{});const qr=result.base64||result.qrcode?.base64;modal('Conectar WhatsApp',qr&&/^data:image\/png;base64,[A-Za-z0-9+/=]+$/.test(qr)?`<div style="text-align:center"><img src="${esc(qr)}" alt="QR Code para parear WhatsApp" style="width:min(280px,100%);height:auto"></div><p class="hint">No celular, abra WhatsApp → Dispositivos conectados → Conectar dispositivo. O código expira; gere outro se necessário.</p>`:'<div class="notice">A instância não retornou um QR Code. Verifique se já está conectada ou tente novamente.</div>','EVOLUTION API');break;}
 case 'session-panel':await sessionPanel();break;
 case 'session-new':form('Novo perfil de navegador',[['kind','Função','select',['Diretor','Instrutor']],['name','Nome do diretor'],['instructorId','Instrutor','select',[['','Selecione para perfil de instrutor'],...data.instructors.filter(x=>x.active).map(x=>[x.id,x.name])]]],{kind:'Diretor'},async values=>{await command('browser-profile',values);await sessionPanel();return 'keep';},'Para instrutor, selecione o cadastro existente. Cada perfil preserva seus próprios dados no navegador.');break;
 case 'session-open':{const [profileId,portal]=arg.split(':');const result=await api('browser/open',{profileId,portal},id());showStudentPortal(profileId,portal,result.session,{name:result.session.profileName,kind:result.session.kind,lease:result.lease});break;}
 case 'assistant-preset':$('#assistant-query').value=arg;assistantQuery(arg);break;
 case 'assistant-query':assistantQuery($('#assistant-query').value);break;
 case 'print':window.print();break;
 case 'export':exportCsv();break;
 case 'queue':queueDialog();break;
 case 'queue-discard':queue=queue.filter(x=>x.id!==arg);await storage(queueKey(),queue);queueDialog();updateConnection();break;
 case 'queue-retry':{const op=queue.find(x=>x.id===arg);if(op)op.error='';await storage(queueKey(),queue);$('#modal').close();await refresh();break;}
 case 'app-update':location.reload();break;
 case 'close-modal':$('#modal').close();$('#modal-body').innerHTML='';break;
 default:{const match=action.match(/^(instructor|vehicle|unit|package|lead|task|template|user)-(new|edit)$/);if(match)resourceForm(match[1],match[2]==='edit'?arg:'');}
 }
}
async function sessionPanel(){const result=await api('browser/profiles');const status=(profile,portal)=>{const session=result.sessions.find(x=>x.profileId===profile.id&&x.portal===portal);const saved=result.preferences.some(x=>x.profileId===profile.id&&x.portal===portal&&x.restore);return session?.browserOpen?(session.authenticated?'Identidade conferida':'Aberto · conferir login')+(session.controlled?' · em atendimento':''):saved?'Restauração pendente':'Não aberto';};modal('Central de sessões do servidor',`<div class="notice green">Abra o navegador do profissional e faça o login na página. Fechar a visualização ou o aplicativo de atendimento conserva o navegador no servidor. Na VPS, ele continuará ligado mesmo com o computador da autoescola desligado.</div>${isManager()?`<div class="actions" style="margin:18px 0">${button('+ Perfil de profissional','session-new','',true)}${data.user.role==='Administrador'?button('Configurar navegador','portal-browser-config'):''}</div>`:''}${table(['Profissional','Função','e-CNH','DETRAN'],result.profiles.filter(x=>x.kind==='Diretor'||x.kind==='Instrutor').map(x=>[esc(x.name),esc(x.kind),`<p>${esc(status(x,'ecnh'))}</p>`+button('Abrir / retomar','session-open',x.id+':ecnh'),`<p>${esc(status(x,'detran'))}</p>`+button('Abrir / retomar','session-open',x.id+':detran')]))}<p class="hint">${result.browser.available?esc(result.browser.name)+' disponível no servidor.':'Instale ou configure Chrome/Chromium no servidor.'} Perfis separados e restauração automática após reinício. O portal pode expirar o login e pedir verificação pessoal. Certificado e leitor precisam estar disponíveis no servidor. Enquanto o piloto roda nesta máquina, ela é o servidor e precisa permanecer ligada.</p><div class="form-actions">${button('Atualizar estado','session-panel')}${button('Fechar','close-modal')}</div>`,'SESSÕES PERSISTENTES · LOGIN MANUAL');}
function documentOpen(x){modal(x.name,`<pre class="document-text">${esc(x.text)}</pre><div class="form-actions">${button('Imprimir / PDF','print')}${button('Fechar','close-modal','',true)}</div>`,'DOCUMENTO · '+date(x.created));}
function queueDialog(){modal('Operações deste dispositivo',queue.length?queue.map(x=>`<div class="task-row"><div><h3>${esc(x.action)}</h3><p>${date(x.created)} ${time(x.created)} · ${esc(x.error||'Aguardando sincronização')}</p><pre class="document-text">${esc(JSON.stringify(x.body,null,2))}</pre><div class="actions">${x.error?button('Tentar novamente','queue-retry',x.id):''}${button('Descartar','queue-discard',x.id)}</div></div></div>`).join(''):'<div class="empty">Nenhuma operação pendente.</div>','SINCRONIZAÇÃO');}
function assistantQuery(text){const q=text.toLowerCase();let rows,title;if(q.includes('aula')){rows=scoped(data.enrollments).filter(e=>!data.lessons.some(x=>x.enrollmentId===e.id&&x.status==='Agendada'&&x.start.slice(0,10)>=today())).map(e=>name('students',e.studentId)+' · categoria '+e.category);title='Matrículas sem próxima aula';}else if(q.includes('parcel')||q.includes('venci')||q.includes('atras')){rows=scoped(data.installments).filter(x=>x.amount>x.paid&&x.due<today()).map(x=>name('students',x.studentId)+' · '+date(x.due)+' · '+money(x.amount-x.paid));title='Parcelas vencidas';}else if(q.includes('veíc')||q.includes('veic')||q.includes('carro')){rows=scoped(data.vehicles).filter(x=>x.status!=='Disponível').map(x=>x.name+' · '+x.status);title='Veículos indisponíveis';}else if(q.includes('pend')||q.includes('tarefa')){rows=attention().map(x=>x.title+' — '+x.detail);title='Pendências';}else{rows=['Consulte aulas, parcelas vencidas, veículos ou pendências.'];title='Escolha um assunto';}$('#assistant-result').innerHTML=`<div class="assistant-result"><h3>${esc(title)}</h3>${rows.length?'<ul>'+rows.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'<p>Nenhum registro encontrado.</p>'}</div>`;}
function exportCsv(){const rows=[['Data','Unidade','Aluno','Tipo','Descrição','Forma','Valor','Recibo'],...scoped(data.entries).map(x=>[x.date,name('units',x.unitId),name('students',x.studentId),x.kind,x.description,x.method,x.amount.toFixed(2).replace('.',','),x.receipt])];const safe=value=>{let s=String(value??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const blob=new Blob(['\ufeff'+rows.map(r=>r.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='financeiro-'+today()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(target){e.preventDefault();if(target.disabled)return;target.disabled=true;Promise.resolve(handle(target.dataset.action,target.dataset.id||'')).catch(err=>toast(err.message)).finally(()=>target.disabled=false);}if(e.target.id==='menu-button')$('#sidebar').classList.toggle('open');if(e.target.closest('#nav a'))$('#sidebar').classList.remove('open');});
document.addEventListener('submit',async e=>{e.preventDefault();if(e.target.id==='login-form'){const values=Object.fromEntries(new FormData(e.target));const submit=e.target.querySelector('[type=submit]');submit.disabled=true;try{const authenticated=await api('auth/login',values);localStorage.setItem('cfc-school',authenticated.schoolId||'');currentStudent='';unit='';data=null;queue=[];if(authenticated.mustChangePassword){location.href='/account/';return;}localStorage.removeItem('cfc-loggedout');if(['Aluno','Instrutor'].includes(authenticated.role)){location.href='/portal/';return;}page='dashboard';await refresh();$('#login-error').textContent='';}catch(err){$('#login-error').textContent=err.message;}finally{submit.disabled=false;}}if(e.target.id==='operation-form'){const formEl=e.target,values={};for(const input of formEl.elements){if(!input.name)continue;values[input.name]=input.type==='checkbox'?input.checked:input.type==='number'?Number(input.value):input.value;}const submit=formEl.querySelector('[type=submit]');submit.disabled=true;const error=formEl.querySelector('#form-error');try{const result=await formCallback(values);if(result!=='keep')$('#modal').close();toast(offline?'Operação pendente de sincronização.':'Operação concluída.');}catch(err){error.textContent=err.message;}finally{submit.disabled=false;}}});
document.addEventListener('change',e=>{if(e.target.id==='unit-filter'){unit=e.target.value;studentsPage=1;if(data.realData)refresh();else render();}if(e.target.id==='agenda-date'){agendaDate=e.target.value||today();if(data.realData)refresh();else render();}});
document.addEventListener('input',e=>{if(e.target.id==='student-search'&&!data.realData){const caret=e.target.selectionStart;search=e.target.value;render();const input=$('#student-search');input.focus();input.setSelectionRange(caret,caret);}});
window.addEventListener('hashchange',()=>{const route=location.hash.slice(1);if(routes.some(([key])=>key===route)){page=route;if(data.realData)refresh();else render();}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#global-search').focus();}if(e.key==='Enter'&&e.target.id==='assistant-query'){e.preventDefault();assistantQuery(e.target.value);}});
const connectionMonitor=CfcConnection.create({
 ping:async()=>{const response=await fetch('/api/health',{cache:'no-store',signal:AbortSignal.timeout(5000)});if(!response.ok)return false;const health=await response.json();return health.application==='cfc-plus'&&health.status==='ok';},
 isOffline:()=>offline,
 onUnavailable:()=>{offline=true;if(data)updateConnection();else $('#login-error').textContent='Servidor indisponível. Tentando reconectar automaticamente…';},
 onRecovery:async()=>{offline=false;await refresh();if(!offline)$('#login-error').textContent='';}
});
window.addEventListener('online',()=>connectionMonitor.probe().catch(()=>{}));window.addEventListener('offline',()=>connectionMonitor.probe().catch(()=>{}));
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')connectionMonitor.probe().catch(()=>{});});
connectionMonitor.start();
if('serviceWorker' in navigator){navigator.serviceWorker.register('/sw.js',{updateViaCache:'none'}).then(r=>r.update()).catch(()=>{});navigator.serviceWorker.addEventListener('controllerchange',()=>{const notice=document.createElement('div');notice.className='app-update-notice';notice.setAttribute('role','status');notice.innerHTML='Aplicativo atualizado. '+button('Aplicar atualização','app-update');document.body.append(notice);});}
api('auth/units').then(us=>{if(us.length){$('#login-unit-label').hidden=false;$('#login-unit').innerHTML='<option value="">Administrador local / selecionar depois</option>'+us.map(u=>`<option value="${esc(u.id)}">${esc(u.name)}</option>`).join('');}}).catch(()=>{});
api('health').then(h=>{if(h.central){$('#school-id-label').hidden=false;$('#school-id').required=true;$('#school-id').value=localStorage.getItem('cfc-school')||'';$('.demo-box').hidden=true;return;}if(!h.demo){$('#login-form [name=password]').value='';$('.demo-box').innerHTML='<strong>Base real importada</strong><p>Use seu acesso da equipe ou o administrador da migração. A senha inicial está no arquivo privado App_Data/acesso-migracao.txt.</p>';}}).catch(()=>{});refresh().catch(e=>toast(e.message));

document.querySelector('#school-id')?.addEventListener('change',async e=>{const id=e.target.value.trim().toLowerCase();e.target.value=id;try{const r=await fetch('/api/auth/units?schoolId='+encodeURIComponent(id));const rows=await r.json();if(!r.ok||!Array.isArray(rows))return;document.querySelector('#login-unit').innerHTML='<option value="">Selecionar unidade depois</option>'+rows.map(u=>'<option value="'+String(u.id).replace(/[&<>"']/g,'')+'">'+String(u.name).replace(/[&<>"']/g,'')+'</option>').join('');const label=document.querySelector('#login-unit-label');if(label)label.hidden=false;}catch{}});
